/* Backlight: TIM1_CH1 / PA8 drives the gate of the Si4599's P-channel FET,
 * a high-side switch that conducts while PA8 is LOW (docs/wiring.md). So the
 * PWM is inverted: brightness % = share of the period PA8 is LOW. backlight_set()
 * takes BRIGHTNESS (100 = full), whatever the polarity. Set ACTIVE_LOW to 0 if
 * the gate is ever driven through an inverting stage (an NPN / N-FET pulling
 * the P-FET gate up to 5 V — worth doing: from a 3.3 V pin, with the FET's
 * source on 5 V, "off" is only Vgs = -1.7 V and may not fully close it; to be
 * measured).
 * That stage is planned (docs/future/build-hardware.md §3, 2N7000) and is a
 * hardware switch-over: the default 1 matches today's direct-drive wiring, and
 * an image built with it on the 2N7000 board turns the backlight OFF at 100 %.
 * Build the new board's image with `python tools/build.py -D BACKLIGHT_ACTIVE_LOW=0`
 * (review C5-HW-04). BACKLIGHT_ACTIVE_LOW itself, with its 0/1 check, lives in
 * app_main.h so the status screen can show the variant. */
#define BACKLIGHT_BOOT_PCT   100u    /* full brightness at boot (PA8 held LOW on the direct drive) */

/* Buttons (input.h): ▶ PE7, ● PE8, ◀ PE9 — dry contacts to ground with a
 * 1 k pull-up, pressed = LOW — and the on-board KEY (PC13, pressed = HIGH) as
 * a second ▶ (docs/future/build-hardware.md §6c). Not connected, the internal
 * pull-ups keep PE7-PE9 reading "not pressed".
 *   ▶ / KEY  tap: next page;      brightness mode: +10 % (100 -> 10)
 *            hold 3 s: brightness mode on / off
 *   ◀        tap: previous page;  brightness mode: -10 % (down to 10)
 *   ●        tap: page action (SNIFF: clean point); brightness mode: -10 %
 *            hold 2 s: page reset (nothing to reset yet: TRIP / PERF later)
 * Brightness mode also ends after BL_MODE_IDLE_MS without a press.
 * Day / night: PE15 reads LOW while the parking lights are on (BC547 on ILL+),
 * filtered by daynight_step(); one brightness profile each, brightness mode
 * edits the active one, and a change of profile fades at BL_RAMP_PCT_S.
 * Profiles live in RAM until the odometer journal (SPI NOR) exists, so a
 * power cycle restores the defaults. */
enum { B_NEXT = 0, B_ACTION, B_PREV, B_KEY, B_N };
#define BL_STEP_PCT      10u
#define BL_MIN_PCT       10u
#define BL_MAX_PCT      100u
#define BL_DAY_PCT      100u     /* profile defaults */
#define BL_NIGHT_PCT     30u
#define BL_MODE_IDLE_MS 5000u
#define BL_RAMP_PCT_S   100u     /* day <-> night fade, % per second */

static btn_t s_btn[B_N] = {
    [B_NEXT]   = { .hold_ms = 3000u },
    [B_ACTION] = { .hold_ms = 2000u },
    [B_PREV]   = { .hold_ms = 0u },
    [B_KEY]    = { .hold_ms = 3000u },
};
static daynight_t s_dn;
static uint8_t  s_bl_profile[2] = { BL_DAY_PCT, BL_NIGHT_PCT };   /* [0] day, [1] night */
static uint8_t  s_bl_pct  = BACKLIGHT_BOOT_PCT;  /* current output %               */
static uint8_t  s_bl_mode = 0;                   /* 0 = pages, 1 = brightness      */
static uint32_t s_bl_mode_t;                     /* last press in brightness mode  */
static uint32_t s_key_cnt = 0;                   /* accepted taps (status screen)  */

/* Set the backlight BRIGHTNESS, 0..100 %. PWM1 output is high while CNT < CCR,
 * so CCR = (ARR+1) * high% / 100 gives an exact 0 % and 100 % (the old
 * ARR * pct / 100 never reached a steady level at 100 %). */
static void backlight_set(uint8_t pct)
{
    if (pct > 100u) pct = 100u;
    s_bl_pct = pct;
    uint32_t high_pct = BACKLIGHT_ACTIVE_LOW ? (100u - pct) : pct;
    __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_1,
                          ((htim1.Init.Period + 1u) * high_pct) / 100u);
}

static uint8_t *bl_active(void) { return &s_bl_profile[s_dn.night ? 1 : 0]; }

/* Brightness mode: step the active profile and show it at once — the change
 * on the panel is the feedback. */
static void bl_edit(int delta, bool wrap)
{
    uint8_t *p = bl_active();
    int v = (int)*p + delta;
    if (v > (int)BL_MAX_PCT) v = wrap ? (int)BL_MIN_PCT : (int)BL_MAX_PCT;
    if (v < (int)BL_MIN_PCT) v = (int)BL_MIN_PCT;
    *p = (uint8_t)v;
    backlight_set(*p);
}

static void btn_tap(uint8_t b, uint32_t t)
{
    s_key_cnt++;
    if (s_bl_mode) {
        s_bl_mode_t = t;
        if (b == B_NEXT || b == B_KEY) bl_edit(+(int)BL_STEP_PCT, true);
        else                           bl_edit(-(int)BL_STEP_PCT, false);
        return;
    }
    switch (b) {
    case B_NEXT:
    case B_KEY:    cluster_ui_next_page(); break;
    case B_PREV:   cluster_ui_prev_page(); break;
    case B_ACTION:
        if (cluster_ui_get_page() == 2u) can_sniff_reset();   /* SNIFF: clean point */
        break;
    default:       break;
    }
}

static void btn_hold(uint8_t b, uint32_t t)
{
    if (b == B_NEXT || b == B_KEY) {          /* brightness mode on / off */
        s_bl_mode = !s_bl_mode;
        s_bl_mode_t = t;
    }
    /* B_ACTION hold: page reset — nothing to reset yet */
}

/* On-board WeAct LED on PE3 (active low). Display-independent heartbeat:
 *   LED off       -> AppMain_Init never reached (RTOS/boot problem)
 *   LED solid on  -> hung inside AppMain_Init (a display init is blocking)
 *   LED blinking  -> the loop runs */
static void heartbeat_led_init(void)
{
    GPIO_InitTypeDef gi = { 0 };
    __HAL_RCC_GPIOE_CLK_ENABLE();
    gi.Pin = GPIO_PIN_3;
    gi.Mode = GPIO_MODE_OUTPUT_PP;
    gi.Pull = GPIO_NOPULL;
    gi.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOE, &gi);
    HAL_GPIO_WritePin(GPIOE, GPIO_PIN_3, GPIO_PIN_RESET); /* on */
}

/* Presses counted by EXTI edges, per button (input.h has the why: an
 * iteration can block ~0.4 s in a full-screen flush, so a tap that starts and
 * ends inside it is never seen by level). A press edge after BTN_DEBOUNCE_MS
 * of quiet counts; closer edges of contact bounce only restart the window. The
 * ISR only ever increments s_presses[] and btn_step() only advances its own
 * copy, so neither side can overwrite the other's update. */
static volatile uint8_t  s_presses[B_N];  /* free-running press count (ISR)     */
static volatile uint32_t s_press_t[B_N];  /* tick of the latest counted press   */
static volatile uint32_t s_edge_t[B_N];   /* tick of the last edge of any kind  */

static const struct { GPIO_TypeDef *port; uint16_t pin; GPIO_PinState down; } BTN_PIN[B_N] = {
    [B_NEXT]   = { GPIOE, GPIO_PIN_7,  GPIO_PIN_RESET },
    [B_ACTION] = { GPIOE, GPIO_PIN_8,  GPIO_PIN_RESET },
    [B_PREV]   = { GPIOE, GPIO_PIN_9,  GPIO_PIN_RESET },
    [B_KEY]    = { GPIOC, GPIO_PIN_13, GPIO_PIN_SET },
};

static bool btn_down(uint8_t b)
{
    return HAL_GPIO_ReadPin(BTN_PIN[b].port, BTN_PIN[b].pin) == BTN_PIN[b].down;
}

/* Count and time of the latest press as one pair: read separately, an EXTI
 * between the two reads paired a new count with the previous press's time
 * (review C7 SW-04). */
static void btn_snapshot(uint8_t b, uint8_t *presses, uint32_t *press_t)
{
    uint32_t pm = __get_PRIMASK();
    __disable_irq();
    *presses = s_presses[b];
    *press_t = s_press_t[b];
    __set_PRIMASK(pm);
}

void EXTI15_10_IRQHandler(void)
{
    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_13);
}

void EXTI9_5_IRQHandler(void)
{
    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_7);
    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_8);
    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_9);
}

void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    for (uint8_t b = 0; b < B_N; b++) {
        if (BTN_PIN[b].pin != GPIO_Pin) continue;
        uint32_t now   = HAL_GetTick();
        bool     quiet = (now - s_edge_t[b]) >= BTN_DEBOUNCE_MS;
        s_edge_t[b] = now;
        if (quiet && btn_down(b)) {
            s_press_t[b] = now;
            s_presses[b]++;
        }
        return;
    }
}

/* KEY on PC13: the WeAct examples wire it with a pull-DOWN, so it reads HIGH
 * while pressed (its RESET and BOOT0 neighbours can't serve as UI keys).
 * ▶ ● ◀ on PE7-PE9 and the parking-light input on PE15: pull-ups, LOW =
 * active. Both edges of the buttons raise EXTI, so a press is caught even
 * while the loop is stuck in a display flush; PE15 is only sampled. */
static void buttons_init(void)
{
    GPIO_InitTypeDef gi = { 0 };
    __HAL_RCC_GPIOC_CLK_ENABLE();
    __HAL_RCC_GPIOE_CLK_ENABLE();
    gi.Mode  = GPIO_MODE_IT_RISING_FALLING;
    gi.Speed = GPIO_SPEED_FREQ_LOW;
    gi.Pin   = GPIO_PIN_13;
    gi.Pull  = GPIO_PULLDOWN;
    HAL_GPIO_Init(GPIOC, &gi);
    gi.Pin   = GPIO_PIN_7 | GPIO_PIN_8 | GPIO_PIN_9;
    gi.Pull  = GPIO_PULLUP;
    HAL_GPIO_Init(GPIOE, &gi);
    gi.Mode  = GPIO_MODE_INPUT;
    gi.Pin   = GPIO_PIN_15;
    gi.Pull  = GPIO_PULLUP;
    HAL_GPIO_Init(GPIOE, &gi);
    HAL_NVIC_SetPriority(EXTI15_10_IRQn, 10, 0);   /* no RTOS calls in the ISRs */
    HAL_NVIC_EnableIRQ(EXTI15_10_IRQn);
    HAL_NVIC_SetPriority(EXTI9_5_IRQn, 10, 0);
    HAL_NVIC_EnableIRQ(EXTI9_5_IRQn);
}

/* PE3 heartbeat repurposed as a backlight-level indicator: it blinks
 * (backlight% / 10) short pulses, then holds a long gap, and repeats. The
 * ongoing blinking still doubles as the "loop alive" signal. PE3 is active-low
 * (RESET = lit, SET = dark). Non-blocking; call every AppMain_Run iteration. */
static void heartbeat_led_tick(uint32_t t)
{
    enum { LED_ON_MS = 130, LED_OFF_MS = 200, LED_GAP_MS = 1200 };
    static uint32_t at = 0;
    static uint8_t  flashes = 0;    /* ON pulses left in this cycle */
    static uint8_t  lit = 0;        /* current electrical state     */

    if (lit) {                                          /* end of an ON pulse */
        if (t - at >= (uint32_t)LED_ON_MS) {
            HAL_GPIO_WritePin(GPIOE, GPIO_PIN_3, GPIO_PIN_SET);   /* dark */
            lit = 0; at = t;
        }
        return;
    }
    /* dark: short gap between pulses, or the long gap between cycles */
    uint32_t wait = (flashes > 0) ? (uint32_t)LED_OFF_MS : (uint32_t)LED_GAP_MS;
    if (t - at < wait) return;

    if (flashes == 0)                                   /* latch level for a new cycle */
        flashes = (s_bl_pct >= 10u) ? (uint8_t)(s_bl_pct / 10u) : 1u;

    HAL_GPIO_WritePin(GPIOE, GPIO_PIN_3, GPIO_PIN_RESET);        /* lit */
    lit = 1; at = t;
    flashes--;
}

void AppMain_Init(void)
{
    heartbeat_led_init();   /* first, before anything that might block */
    buttons_init();         /* KEY PC13, ▶ ● ◀ PE7-PE9, parking lights PE15 */

    lv_port_disp_init();          /* lv_init + the 4" ILI9488 display (default) */
    cluster_app_init(&hfdcan1);   /* build the 3 pages on the 4" + start OBD-II  */
    st7735_status_init();         /* small status screen on SPI4 (2nd display)   */
    gps_init();                   /* USART2: listens only; finds the module later */

    /* backlight: TIM1_CH1 / PA8 -> Si4599 P-FET gate, per docs/wiring.md */
    HAL_TIM_PWM_Start(&htim1, TIM_CHANNEL_1);
    backlight_set(BACKLIGHT_BOOT_PCT);

    /* Init is done: from here the watchdog must be fed every iteration
     * (started with the long boot timeout in main.c). */
    fault_wdg_run_mode();
}

/* Longest superloop period (start to start, including the 5 ms osDelay) over
 * the last full second, shown on DIAG. Wall-clock is right here: it measures
 * how long the loop stalls, which is exactly what the display path costs. */
static uint32_t s_loop_max_ms;

uint32_t app_loop_max_ms(void) { return s_loop_max_ms; }

static void loop_time_tick(uint32_t t)
{
    static uint32_t prev, win_start, win_max;
    uint32_t dt = t - prev;
    prev = t;
    if (dt > win_max) win_max = dt;
    if (t - win_start >= 1000u) {
        s_loop_max_ms = win_max;
        win_max = 0;
        win_start = t;
    }
}

void AppMain_Run(void)
{
    /* PE3 shows the backlight level as a blink code (also the loop heartbeat) */
    uint32_t t = HAL_GetTick();
    loop_time_tick(t);
    heartbeat_led_tick(t);

    /* Buttons -> taps / holds -> actions (see the block above btn_tap()). */
    for (uint8_t b = 0; b < B_N; b++) {
        uint8_t  presses;
        uint32_t press_t;
        btn_snapshot(b, &presses, &press_t);
        btn_out_t o = btn_step(&s_btn[b], btn_down(b), presses, press_t, t);
        for (uint8_t k = 0; k < o.taps; k++) btn_tap(b, t);
        if (o.hold) btn_hold(b, t);
    }
    if (s_bl_mode && (t - s_bl_mode_t) >= BL_MODE_IDLE_MS) s_bl_mode = 0;

    /* Day / night profile, faded 1 % at a time. */
    daynight_step(&s_dn, HAL_GPIO_ReadPin(GPIOE, GPIO_PIN_15) == GPIO_PIN_RESET, t);
    {
        static uint32_t ramp_t;
        uint8_t target = *bl_active();
        if (s_bl_pct != target && (t - ramp_t) >= 1000u / BL_RAMP_PCT_S) {
            ramp_t = t;
            backlight_set((uint8_t)(s_bl_pct < target ? s_bl_pct + 1u : s_bl_pct - 1u));
        }
    }
    bool key_now = btn_down(B_KEY);
#if FAULT_TEST
    /* Bench check of the watchdog / fault record (fault.h). */
    if (key_now && s_btn[B_KEY].prev && (t - s_btn[B_KEY].down_t) >= FAULT_TEST_HOLD_MS)
        fault_selftest();
#endif

    lv_port_disp_service();   /* repaint / re-init the 4" panel after SPI errors */
    st7735_status_service(t); /* same for the small screen: restart SPI4, repaint */
    lv_timer_handler();   /* LVGL rendering for both displays */
    gps_poll();           /* GPS: drain the UART ring, decode, keep the link     */
    cluster_app_run();    /* OBD-II: RX drain, request scheduler, UI refresh, watchdog */

    /* refresh the small status screen a few times a second */
    static uint32_t last_status_ms = 0u;
    uint32_t now = lv_tick_get();
    if (now - last_status_ms >= 250u) {
        last_status_ms = now;
        /* -1 = nothing to show ("--"): never decoded (NaN), stale, or the
         * link is down — the same test as the main display (cluster_policy.h).
         * 0 would be a believable reading, and casting NaN to int is UB. */
        uint32_t tn = HAL_GetTick();
        st_link_t link = !g_obd.can_ok ? ST_LINK_DOWN
                       : (policy_ecm_fresh(&g_obd, tn) ? ST_LINK_ECM : ST_LINK_BUS);
        st7735_status_set(policy_shown(&g_obd, M_SPEED, tn)   ? (int32_t)g_obd.speed : -1,
                          policy_shown(&g_obd, M_RPM, tn)     ? (int32_t)g_obd.rpm   : -1,
                          policy_shown(&g_obd, M_BATTERY, tn) ? (int32_t)(g_obd.battery * 10.0f + 0.5f) : -1,
                          link);
        /* KEY diagnostic: page index, live PC13 level, accepted-press count */
        st7735_status_key_dbg(cluster_ui_get_page(), key_now, s_key_cnt);
        /* in brightness mode: overlay the current backlight level on the small screen */
        st7735_status_backlight(s_bl_mode, s_bl_pct, s_dn.night);
    }

    /* Only a fully completed iteration (render + OBD + UI) feeds the watchdog,
     * so a hang anywhere in the loop resets the board instead of freezing the
     * last frame on the panel. */
    fault_wdg_kick();
}
